 const connect=()=>run(async()=>{if(settings.demo)throw new Error('Finish the sample tour first. Remove sample data in Settings before connecting Drive.');const email=await connectGoogle();await updateSettings({driveEmail:email});await scheduleSync(true).catch(()=>notify('Use Sync now if background scheduling is unavailable.'));await syncDrive();await reload();setSheet(null);notify('Google Drive connected. Your first sync is complete.');});
